/* Service worker for OA Trainer (static export). Generated by scripts/build-sw.mjs.
 * - Precaches every file of the static build so the app works fully offline.
 * - Navigations: network-first (fresh deploys) with cache fallback.
 * - Hashed static assets: cache-first.
 * - Supabase (cross-origin) requests are never intercepted.
 */
const PRECACHE = self.__PRECACHE_MANIFEST;
const VERSION = self.__PRECACHE_VERSION;
const CACHE = "oa-precache-" + VERSION;
const RUNTIME = "oa-runtime";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // add in small batches so one failure doesn't abort everything
      for (let i = 0; i < PRECACHE.length; i += 20) {
        const batch = PRECACHE.slice(i, i + 20);
        await Promise.all(
          batch.map((u) => cache.add(new Request(u, { cache: "reload" })).catch(() => undefined)),
        );
      }
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith("oa-precache-") && k !== CACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

function candidates(url) {
  const p = url.pathname;
  const out = [p];
  if (!p.endsWith("/") && !/\.[a-z0-9]+$/i.test(p)) out.push(p + "/");
  if (p.endsWith("/")) out.push(p + "index.html");
  return out;
}

async function fromCache(request) {
  const url = new URL(request.url);
  for (const c of candidates(url)) {
    const hit = await caches.match(c, { ignoreSearch: true });
    if (hit) return hit;
  }
  return undefined;
}

async function networkFirst(request, timeoutMs) {
  try {
    const res = await Promise.race([
      fetch(request),
      new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), timeoutMs)),
    ]);
    if (res && res.ok) {
      const copy = res.clone();
      caches.open(RUNTIME).then((c) => c.put(request, copy)).catch(() => {});
    }
    return res;
  } catch (e) {
    const hit = (await fromCache(request)) || (await caches.match(request));
    if (hit) return hit;
    if (request.mode === "navigate") {
      const home = await caches.match("/", { ignoreSearch: true });
      if (home) return home;
    }
    throw e;
  }
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === "navigate") {
    event.respondWith(networkFirst(req, 4000));
    return;
  }
  if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/")) {
    event.respondWith(
      (async () => (await caches.match(req, { ignoreSearch: true })) || fetch(req))(),
    );
    return;
  }
  event.respondWith(networkFirst(req, 4000));
});
